select case when s.sqft >= 16701 then 'high' when s.sqft >= 4831 then 'mid' else 'low' end as sqft_bucket, sum(case when o.status = 'PENDING' then 1 else 0 end) as pending_count from orders o left join stores s on o.store_id = s.id full outer join customers c on o.customer_id = c.id where o.channel is null group by case when s.sqft >= 16701 then 'high' when s.sqft >= 4831 then 'mid' else 'low' end order by sqft_bucket;
